import {resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {discoverInventory,validateInventory,sourceHash} from '../scripts/quality-inventory';
const base='.planning/memory-resilience/',read=(p:string)=>JSON.parse(readFileSync(p,'utf8'));
const path=base+'evidence/B11.74.4.json',record=read(path),catalog=discoverInventory(process.cwd());
