for(const input of [...record.sourceInputs,...record.otherInputs])assert.equal(input.sourceHash,sourceHash(readFileSync(input.path,'utf8')));
for(const input of record.sourceInputs)for(const rows of [record.diagnosticCoverage.sourceInputs,record.decisionChecks.sourceInputs,record.native.sourceInputs])assert.equal(rows.find((r:any)=>r.path===input.path).sourceHash,input.sourceHash);
const coverage=createCoverageMap(record.diagnosticCoverage.measurement.rawCoverage);
const expected=[[100,100,100,97.29],[98,100,98.18,96.15],[99.56,100,99.61,97.12],[100,100,100,100],[98,93.42,95.27,58.97]];
for(const [index,entry]of record.diagnosticCoverage.measurement.files.entries()){assert.deepEqual(coverage.fileCoverageFor(resolve(entry.path)).toSummary().data,entry.metrics);assert.deepEqual(['lines','functions','statements','branches'].map(k=>entry.metrics[k].pct),expected[index]);}
for(const run of [record.checks[0],...record.native.runs]){assert.equal(run.exit,0);assert(run.output.includes('136 pass')&&run.output.includes('0 fail')&&run.output.includes('1273 expect()'));}
